export type ParsedRecoverResolutionInstruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    caller: TAccountMetas[0];
    market: TAccountMetas[1];
    routeState: TAccountMetas[2];
    registry: TAccountMetas[3];
    resolution: TAccountMetas[4];
    vault: TAccountMetas[5];
    primaryBtc: TAccountMetas[6];
    primaryCollateral: TAccountMetas[7];
    guardBtc: TAccountMetas[8];
    guardCollateral: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: RecoverResolutionInstructionData;
};

export function parseRecoverResolutionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRecoverResolutionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      caller: getNextAccount(),
      market: getNextAccount(),
      routeState: getNextAccount(),
      registry: getNextAccount(),
      resolution: getNextAccount(),
      vault: getNextAccount(),
      primaryBtc: getNextAccount(),
      primaryCollateral: getNextAccount(),
      guardBtc: getNextAccount(),
      guardCollateral: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getRecoverResolutionInstructionDataDecoder().decode(instruction.data),
  };
}
